using Challenge;void C(string id,Func<bool> f){try{Console.WriteLine($"{id}|{(f()?"pass":"fail")}");}catch{Console.WriteLine($"{id}|fail");}}C("C01",()=>{var s=new LinkService(new MemoryLinkStore(),new Codes("a"));return s.Resolve(s.Create("https://example.com/x"))=="https://example.com/x";});C("C02",()=>{try{new LinkService(new MemoryLinkStore(),new Codes("a")).Create("javascript:alert(1)");return false;}catch(ArgumentException){return true;}});C("C03",()=>{var d=new MemoryLinkStore();d.TryAdd("x","https://old");var s=new LinkService(d,new Codes("x","y"));return s.Create("https://new")=="y"&&d.Get("x")=="https://old";});C("C04",()=>{var d=new MemoryLinkStore();var a=new LinkService(d,new Codes("a","b"));var b=new LinkService(d,new Codes("a","c"));return Task.WhenAll(Task.Run(()=>a.Create("https://a")),Task.Run(()=>b.Create("https://b"))).Result.Distinct().Count()==2;});C("C05",()=>new LinkService(new MemoryLinkStore(),new Codes("a")).Resolve("missing") is null);class Codes(params string[] values):ICodeSource{int i;public string Next()=>values[Math.Min(Interlocked.Increment(ref i)-1,values.Length-1)];}
